"""One-off GENERATOR for the PDF extraction fixtures (M4 / FEAT-003).

This is NOT a pytest test: the leading underscore keeps pytest from collecting
it, and it is meant to be run manually with

    uv run python tests/fixtures/_generate_pdf_fixtures.py

to populate ``tests/fixtures/pdf/`` with the PDFs the ``test_pdf.py`` unit tests
consume. The PDFs are GENERATED by reportlab (BSD, dev-only dependency) so they
are fully deterministic and need no network — unlike the HTML fixtures, which
are real downloaded snapshots.

Each technical PDF exercises the SPEC §4 PDF path:

- a TITLE in a larger font (so it is inferred as a ``heading`` level 1) and
  section headings in an intermediate font (level 2);
- at least one TABLE (``extract_tables``), including, in one document, a table
  with NO header row (to exercise ``table_no_header``);
- a running HEADER and FOOTER repeated on EVERY page (so, being on >50% of the
  pages, they are removed by the repeated-chrome rule);
- several pages of body paragraphs.

The fourth PDF has NO extractable text at all — only a drawn vector rectangle —
to exercise the ``extraction_empty`` (HTTP 422) case.

Every generated PDF is documented in ``tests/fixtures/pdf/SOURCES.md``.
"""

from __future__ import annotations

from pathlib import Path

from reportlab.lib.pagesizes import LETTER
from reportlab.pdfgen import canvas

_OUTPUT_DIR = Path(__file__).resolve().parent / "pdf"

_PAGE_WIDTH, _PAGE_HEIGHT = LETTER
_MARGIN = 72.0  # 1 inch

# Font sizes: title > section heading > body. The extractor infers the two
# largest sizes above body as heading levels 1 and 2.
_TITLE_SIZE = 24.0
_HEADING_SIZE = 16.0
_BODY_SIZE = 11.0

_HEADER_TEXT = "NINA Technical Reference — Confidential Draft"
_FOOTER_TEXT = "© 2026 NINA Project — Page chrome, not content"


def _draw_running_chrome(pdf: canvas.Canvas, page_no: int) -> None:
    """Draw the repeated header and footer that must be stripped from the IR."""
    pdf.setFont("Helvetica", 9.0)
    # Header near the very top of the page.
    pdf.drawString(_MARGIN, _PAGE_HEIGHT - 36.0, _HEADER_TEXT)
    # Footer near the very bottom of the page.
    pdf.drawString(_MARGIN, 30.0, f"{_FOOTER_TEXT} {page_no}")


def _draw_wrapped(
    pdf: canvas.Canvas, text: str, x: float, y: float, size: float, font: str
) -> float:
    """Draw ``text`` as one line and return the next baseline y."""
    pdf.setFont(font, size)
    pdf.drawString(x, y, text)
    return y - size * 1.6


def _new_page_cursor() -> float:
    """Return the starting y cursor just below the header band."""
    return _PAGE_HEIGHT - 90.0


def _technical_pdf(
    path: Path,
    title: str,
    sections: list[tuple[str, list[str]]],
    table: tuple[list[str], list[list[str]]],
    table_has_header: bool,
) -> None:
    """Generate one multi-page technical PDF with title, headings and a table."""
    pdf = canvas.Canvas(str(path), pagesize=LETTER)
    page_no = 1
    _draw_running_chrome(pdf, page_no)

    y = _new_page_cursor()
    y = _draw_wrapped(pdf, title, _MARGIN, y, _TITLE_SIZE, "Helvetica-Bold")
    y -= 10.0

    for heading, paragraphs in sections:
        if y < 160.0:
            pdf.showPage()
            page_no += 1
            _draw_running_chrome(pdf, page_no)
            y = _new_page_cursor()
        y = _draw_wrapped(pdf, heading, _MARGIN, y, _HEADING_SIZE, "Helvetica-Bold")
        for para in paragraphs:
            if y < 120.0:
                pdf.showPage()
                page_no += 1
                _draw_running_chrome(pdf, page_no)
                y = _new_page_cursor()
            y = _draw_wrapped(pdf, para, _MARGIN, y, _BODY_SIZE, "Helvetica")
        y -= 8.0

    # Always start the table on a fresh page so its box is clean.
    pdf.showPage()
    page_no += 1
    _draw_running_chrome(pdf, page_no)
    y = _new_page_cursor()
    y = _draw_wrapped(
        pdf, "Reference Table", _MARGIN, y, _HEADING_SIZE, "Helvetica-Bold"
    )
    _draw_table(pdf, table[0], table[1], _MARGIN, y - 10.0, table_has_header)

    pdf.showPage()
    pdf.save()


def _draw_table(
    pdf: canvas.Canvas,
    headers: list[str],
    rows: list[list[str]],
    x: float,
    y: float,
    draw_header: bool,
) -> None:
    """Draw a simple ruled grid so pdfplumber's extract_tables detects it."""
    col_count = len(headers) if draw_header else len(rows[0])
    col_width = 150.0
    row_height = 22.0
    grid = ([headers] if draw_header else []) + rows
    table_width = col_width * col_count
    table_height = row_height * len(grid)

    # Horizontal rules.
    for i in range(len(grid) + 1):
        line_y = y - i * row_height
        pdf.line(x, line_y, x + table_width, line_y)
    # Vertical rules.
    for j in range(col_count + 1):
        line_x = x + j * col_width
        pdf.line(line_x, y, line_x, y - table_height)

    pdf.setFont("Helvetica", _BODY_SIZE)
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            pdf.drawString(
                x + j * col_width + 5.0,
                y - (i + 1) * row_height + 6.0,
                cell,
            )


def _textless_pdf(path: Path) -> None:
    """Generate a PDF with NO text runs — only a drawn vector rectangle."""
    pdf = canvas.Canvas(str(path), pagesize=LETTER)
    pdf.setStrokeColorRGB(0.1, 0.1, 0.1)
    pdf.setFillColorRGB(0.8, 0.8, 0.8)
    pdf.rect(150.0, 400.0, 300.0, 200.0, stroke=1, fill=1)
    pdf.showPage()
    pdf.save()


def _generate() -> None:
    _OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

    _technical_pdf(
        _OUTPUT_DIR / "api_reference.pdf",
        title="NINA API Reference",
        sections=[
            (
                "Authentication",
                [
                    "Every request must carry the X-Api-Key header.",
                    "Keys are shown once at creation and stored only as a hash.",
                    "Rotating a key invalidates the previous value immediately.",
                ],
            ),
            (
                "Rate Limits",
                [
                    "The default quota is one thousand requests per hour.",
                    "Exceeding the quota returns a 429 response with a reset time.",
                    "Burst traffic is smoothed with a token-bucket algorithm.",
                ],
            ),
            (
                "Errors",
                [
                    "Errors follow the envelope error.code and error.message.",
                    "A blocked destination returns the blocked_destination code.",
                    "An empty extraction returns the extraction_empty code.",
                ],
            ),
        ],
        table=(
            ["Code", "Status", "Meaning"],
            [
                ["invalid_url", "400", "URL malformed or forbidden scheme"],
                ["too_large", "413", "Body exceeded the size limit"],
                ["extraction_empty", "422", "No extractable text was found"],
                ["timeout", "504", "Connect or total timeout exceeded"],
            ],
        ),
        table_has_header=True,
    )

    _technical_pdf(
        _OUTPUT_DIR / "config_guide.pdf",
        title="NINA Configuration Guide",
        sections=[
            (
                "Environment",
                [
                    "Settings map one-to-one to upper-cased environment names.",
                    "The dev environment uses SeaweedFS for S3-compatible storage.",
                    "Production reads the same keys from the deployment secrets.",
                ],
            ),
            (
                "Fetcher Limits",
                [
                    "The body limit is fifteen megabytes read in streaming mode.",
                    "The total timeout is twenty seconds end to end.",
                    "At most five redirects are followed, each re-validated.",
                ],
            ),
            (
                "Rendering",
                [
                    "Rendering is attempted only when the main text is too short.",
                    "A single page is given fifteen seconds to reach networkidle.",
                    "Every browser request is validated by the destination guard.",
                ],
            ),
        ],
        table=(
            ["Setting", "Default"],
            [
                ["max_body_bytes", "15728640"],
                ["total_timeout", "20"],
                ["connect_timeout", "5"],
                ["render_min_text_chars", "500"],
            ],
        ),
        table_has_header=True,
    )

    _technical_pdf(
        _OUTPUT_DIR / "release_notes.pdf",
        title="NINA Release Notes",
        sections=[
            (
                "Milestone M3",
                [
                    "The HTML to IR extractor landed with full block coverage.",
                    "Tables, code and admonitions are preserved from main content.",
                    "Site chrome such as navigation and footers is removed.",
                ],
            ),
            (
                "Milestone M4",
                [
                    "Browser rendering now routes every request through the guard.",
                    "PDF extraction reads documents page by page with pdfplumber.",
                    "Headers and footers repeated across pages are stripped out.",
                ],
            ),
        ],
        # A header-less table: the first row has a blank leading cell, so no
        # complete header row is detectable and the extractor emits the
        # table_no_header warning.
        table=(
            [],
            [
                ["", "HTML to IR", "done"],
                ["M4", "Browser and PDF", "done"],
                ["M5", "Resolve endpoint", "pending"],
            ],
        ),
        table_has_header=False,
    )

    _textless_pdf(_OUTPUT_DIR / "textless.pdf")

    for pdf_path in sorted(_OUTPUT_DIR.glob("*.pdf")):
        print(f"generated {pdf_path.name:<24} {pdf_path.stat().st_size:>8} bytes")


if __name__ == "__main__":
    _generate()
